<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'; import { api, errorMessage } from '../api'; import { auth } from '../auth';
type Order={_id:string;folio:string;status:string;complaint:string;diagnosis?:string;quote?:number;authorization:{status:string};vehicleId?:{plate:string;brand:string;model:string;year:number}}; type Vehicle={_id:string;plate:string;brand:string;model:string;year:number};
const orders=ref<Order[]>([]), vehicles=ref<Vehicle[]>([]), error=ref(''), dialog=ref(false), editor=ref<Order|null>(null), newOrder=ref({vehicleId:'',complaint:''}); const staff=computed(()=>auth.user?.role!=='CUSTOMER'); const statuses=['RECEIVED','DIAGNOSIS','PENDING_AUTHORIZATION','AUTHORIZED','PENDING_PARTS','IN_REPAIR','PENDING_VALIDATION','READY_FOR_DELIVERY','DELIVERED','CANCELLED'];
async function load(){try{orders.value=(await api.get('/orders')).data;if(staff.value)vehicles.value=(await api.get('/vehicles')).data}catch(e){error.value=errorMessage(e)}}onMounted(load);
async function create(){try{await api.post('/orders',newOrder.value);dialog.value=false;newOrder.value={vehicleId:'',complaint:''};await load()}catch(e){error.value=errorMessage(e)}} async function save(){if(!editor.value)return;try{await api.patch(`/orders/${editor.value._id}`,{status:editor.value.status,diagnosis:editor.value.diagnosis,quote:editor.value.quote,authorizationStatus:editor.value.authorization.status});editor.value=null;await load()}catch(e){error.value=errorMessage(e)}}
</script>
<template><div class="d-flex align-center mb-5"><h1 class="text-h4">{{staff?'Órdenes de reparación':'Mis órdenes'}}</h1><v-spacer/><v-btn v-if="staff" color="primary" @click="dialog=true">Nueva orden</v-btn></div><v-alert v-if="error" type="error" closable @click:close="error=''">{{error}}</v-alert><v-card><v-table><thead><tr><th>Folio</th><th>Vehículo</th><th>Motivo</th><th>Estado</th><th v-if="staff">Acción</th></tr></thead><tbody><tr v-for="order in orders" :key="order._id"><td>{{order.folio}}</td><td>{{order.vehicleId ? `${order.vehicleId.plate} · ${order.vehicleId.brand} ${order.vehicleId.model}` : '—'}}</td><td>{{order.complaint}}</td><td><v-chip size="small" color="primary">{{order.status}}</v-chip></td><td v-if="staff"><v-btn size="small" variant="text" @click="editor=JSON.parse(JSON.stringify(order))">Actualizar</v-btn></td></tr></tbody></v-table></v-card>
<v-dialog v-model="dialog" max-width="550"><v-card title="Nueva orden"><v-card-text><v-select v-model="newOrder.vehicleId" :items="vehicles" item-value="_id" :item-title="v=>`${v.plate} · ${v.brand} ${v.model}`" label="Vehículo"/><v-textarea v-model="newOrder.complaint" label="Motivo de ingreso"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">Cancelar</v-btn><v-btn color="primary" @click="create">Crear</v-btn></v-card-actions></v-card></v-dialog>
<v-dialog :model-value="!!editor" max-width="600" @update:model-value="v=>!v&&(editor=null)"><v-card v-if="editor" title="Actualizar orden"><v-card-text><v-select v-model="editor.status" :items="statuses" label="Estado"/><v-textarea v-model="editor.diagnosis" label="Diagnóstico"/><v-text-field v-model.number="editor.quote" label="Presupuesto" type="number"/><v-select v-model="editor.authorization.status" :items="['NOT_REQUESTED','PENDING','APPROVED','REJECTED']" label="Autorización"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="editor=null">Cancelar</v-btn><v-btn color="primary" @click="save">Guardar</v-btn></v-card-actions></v-card></v-dialog></template>
